package org.apache.dubbo.common.utils;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Future;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test for {@link ReflectUtils#getReturnTypes(Method)} focusing on the fix for TypeVariable support.
 */
public class ReflectUtilsTest {

    // Test interface with generic Future return type
    public interface TypeClass<T> {
        CompletableFuture<T> getGenericFuture();
    }

    // Concrete implementation for testing
    public static class ConcreteTypeClass implements TypeClass<String> {
        @Override
        public CompletableFuture<String> getGenericFuture() {
            return CompletableFuture.completedFuture("test");
        }
    }

    // Another test interface with nested generic
    public interface MultiGenericType<T, R> {
        Future<T> getFuture();
        CompletableFuture<R> getCompletableFuture();
    }

    // Interface for testGetReturnTypesWithParameterizedType
    public interface NonGenericFuture {
        Future<String> getFuture();
    }

    // Interface for testGetReturnTypesWithRawFuture
    public interface RawFuture {
        Future getFuture();
    }

    // Interface for testGetReturnTypesWithNonFutureMethod
    public interface NonFuture {
        String getString();
    }

    // Interface for testGetReturnTypesWithBoundedTypeVariable
    public interface BoundedTypeClass<T extends Number> {
        CompletableFuture<T> getBoundedFuture();
    }

    // Interface for testGetReturnTypesWithNestedParameterizedType
    public interface NestedGeneric<T> {
        CompletableFuture<List<T>> getNestedFuture();
    }

    @Test
    public void testGetReturnTypesWithTypeVariable() throws Exception {
        // Get the method from the generic interface
        Method method = TypeClass.class.getMethod("getGenericFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        // Expected: returnType should be the upper bound of TypeVariable (Object.class)
        // genericReturnType should be the TypeVariable itself
        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // The first element should be the resolved class (upper bound of TypeVariable)
        assertTrue(returnTypes[0] instanceof Class);
        // Since T has no explicit bound, its upper bound is Object
        assertEquals(Object.class, returnTypes[0]);

        // The second element should be the TypeVariable
        assertTrue(returnTypes[1] instanceof TypeVariable);
        TypeVariable<?> typeVar = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVar.getName());
    }

    @Test
    public void testGetReturnTypesWithConcreteType() throws Exception {
        // Get the method from concrete implementation
        Method method = ConcreteTypeClass.class.getMethod("getGenericFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        // Expected: returnType should be String.class
        // genericReturnType should be String.class (since type is resolved)
        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // Both should be String.class
        assertEquals(String.class, returnTypes[0]);
        assertEquals(String.class, returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithParameterizedType() throws Exception {
        Method method = NonGenericFuture.class.getMethod("getFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);
        assertEquals(String.class, returnTypes[0]);
        assertTrue(returnTypes[1] instanceof Class);
        assertEquals(String.class, returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithRawFuture() throws Exception {
        Method method = RawFuture.class.getMethod("getFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        // Should return null for both since Future is raw
        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);
        assertNull(returnTypes[0]);
        assertNull(returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithNonFutureMethod() throws Exception {
        Method method = NonFuture.class.getMethod("getString");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);
        assertEquals(String.class, returnTypes[0]);
        assertEquals(String.class, returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithBoundedTypeVariable() throws Exception {
        Method method = BoundedTypeClass.class.getMethod("getBoundedFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // The bound should be Number.class
        assertEquals(Number.class, returnTypes[0]);
        assertTrue(returnTypes[1] instanceof TypeVariable);
        TypeVariable<?> typeVar = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVar.getName());
        assertEquals(Number.class, typeVar.getBounds()[0]);
    }

    @Test
    public void testGetReturnTypesWithMultipleTypeVariables() throws Exception {
        // Get methods from multi-generic interface
        Method futureMethod = MultiGenericType.class.getMethod("getFuture");
        Method completableFutureMethod = MultiGenericType.class.getMethod("getCompletableFuture");

        Type[] futureReturnTypes = ReflectUtils.getReturnTypes(futureMethod);
        Type[] completableFutureReturnTypes = ReflectUtils.getReturnTypes(completableFutureMethod);

        // Test getFuture() method
        assertNotNull(futureReturnTypes);
        assertEquals(2, futureReturnTypes.length);
        assertEquals(Object.class, futureReturnTypes[0]); // Upper bound of T
        assertTrue(futureReturnTypes[1] instanceof TypeVariable);
        assertEquals("T", ((TypeVariable<?>) futureReturnTypes[1]).getName());

        // Test getCompletableFuture() method
        assertNotNull(completableFutureReturnTypes);
        assertEquals(2, completableFutureReturnTypes.length);
        assertEquals(Object.class, completableFutureReturnTypes[0]); // Upper bound of R
        assertTrue(completableFutureReturnTypes[1] instanceof TypeVariable);
        assertEquals("R", ((TypeVariable<?>) completableFutureReturnTypes[1]).getName());
    }

    @Test
    public void testGetReturnTypesWithNestedParameterizedType() throws Exception {
        // We need to use a helper class to get the actual method
        class Helper implements NestedGeneric<String> {
            @Override
            public CompletableFuture<List<String>> getNestedFuture() {
                return CompletableFuture.completedFuture(new ArrayList<>());
            }
        }

        Method method = Helper.class.getMethod("getNestedFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // The return type should be List.class
        // The generic return type should be ParameterizedType List<String>
        assertEquals(List.class, returnTypes[0]);
        assertTrue(returnTypes[1] instanceof ParameterizedType);
        ParameterizedType pt = (ParameterizedType) returnTypes[1];
        assertEquals(List.class, pt.getRawType());
        assertEquals(String.class, pt.getActualTypeArguments()[0]);
    }
}

